	(1,'P2026042501-A',1,'低硫高热值推荐方案-A',2535000.00,92.00,84.00,88.00,89.20,1,'预测灰分10.64%，硫分0.652%，水分6.84%，发热量6048kcal/kg，满足订单硬约束。','质量分较高；成本因使用高热值低硫产品略高；库存稳定性良好。','low','executed','优先使用低硫高热值精煤PB2026042501-CL，并搭配洗选降灰精煤PB2026042502-CL。','命中低硫煤优先、灰分约束、发热量下限、库存可用性规则。','参考历史低硫动力煤配煤案例。','在质量达标前提下兼顾库存消耗和成本控制。','方案已执行并生成最终产品批次FP2026042501，最终质检合格。','风险较低，需关注PB2026042502-CL库存余量。','后续同类订单可优先保留PB2026042501-CL作为低硫主配资源。','RAG关键词检索配置',1,1,'2026-04-25 16:14:38','2026-04-25 16:14:38','FP2026042501','shipped','system',NULL),
	(2,'P2026042502-RISK',2,'严格低硫订单风险方案',1712000.00,76.00,82.00,73.00,77.10,1,'预测灰分13.08%，硫分0.598%，发热量5750kcal/kg，理论满足订单，但硫分接近0.60%上限。','质量余量不足，成本中等，库存压力较高。','medium','executed','该方案满足硬约束但硫分安全余量过小，执行时需加强最终质检。','命中高硫煤限配、低硫煤优先和风险提示规则。','参考低硫订单案例，但本订单硫分约束更严格。','受库存限制，方案保留较少质量余量。','方案执行后最终质检硫分0.610%，超过订单硫分上限。','硫分接近上限，不建议作为长期稳定方案。','建议增加低硫高热值精煤比例，减少PB2026042502-CL占比。','RAG关键词检索配置',1,1,'2026-04-25 16:14:38','2026-04-25 16:14:38','FP2026042502','inspected','system',NULL),
	(3,'P2026042503-COST',3,'成本优先候选方案',2012500.00,81.00,91.00,83.00,84.40,1,'预测灰分15.18%，硫分0.568%，水分8.93%，发热量5375kcal/kg，满足成本优先订单要求。','成本优势明显，质量满足但水分余量一般。','medium','generated','为满足成本优先目标，使用成本优先动力煤产品PB2026042601-CL，并搭配低硫高热值精煤。','命中低成本煤使用边界、库存可用性和灰分约束规则。','参考成本优先动力煤案例。','该方案适合质量要求相对宽松、成本敏感的订单。','方案尚未发运，可作为候选方案展示。','水分接近订单上限，执行前建议复检产品批次。','若客户质量要求提高，应增加PB2026042501-CL比例。','RAG关键词检索配置',1,1,'2026-04-25 16:14:38','2026-04-25 16:14:38',NULL,'not_executed','system',NULL),
