# 转储表 experiment_record
# ------------------------------------------------------------

DROP TABLE IF EXISTS `experiment_record`;

CREATE TABLE `experiment_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `experiment_code` varchar(50) DEFAULT NULL COMMENT '实验编号，同一次生成请求使用同一编号',
  `order_id` bigint DEFAULT NULL COMMENT '订单ID',
  `model_name` varchar(50) DEFAULT NULL COMMENT '模型名称：优化前/优化后模型或系统枚举',
  `plan_id` bigint DEFAULT NULL COMMENT '生成的方案ID',
  `total_cost` decimal(12,2) DEFAULT NULL COMMENT '总成本',
  `avg_ash` decimal(6,2) DEFAULT NULL COMMENT '预测灰分',
  `avg_sulfur` decimal(6,3) DEFAULT NULL COMMENT '预测硫分',
  `avg_moisture` decimal(6,2) DEFAULT NULL COMMENT '预测水分',
  `avg_calorific` decimal(8,2) DEFAULT NULL COMMENT '预测发热量',
  `quality_score` decimal(6,2) DEFAULT NULL COMMENT '质量匹配评分',
  `cost_score` decimal(6,2) DEFAULT NULL COMMENT '成本评分',
  `inventory_score` decimal(6,2) DEFAULT NULL COMMENT '库存合理性评分',
  `final_score` decimal(6,2) DEFAULT NULL COMMENT '综合评分',
  `constraint_hit` text COMMENT '命中的约束、风险和评分说明JSON',
  `risk_warning` text COMMENT '风险提示',
  `explain_text` text COMMENT '模型生成理由和评分解释',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_experiment_order` (`order_id`),
  KEY `idx_experiment_code` (`experiment_code`),
  KEY `idx_experiment_model` (`model_name`),
  KEY `idx_experiment_plan` (`plan_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='模型配煤方案质量评估实验记录';

LOCK TABLES `experiment_record` WRITE;
/*!40000 ALTER TABLE `experiment_record` DISABLE KEYS */;

INSERT INTO `experiment_record` (`id`, `experiment_code`, `order_id`, `model_name`, `plan_id`, `total_cost`, `avg_ash`, `avg_sulfur`, `avg_moisture`, `avg_calorific`, `quality_score`, `cost_score`, `inventory_score`, `final_score`, `constraint_hit`, `risk_warning`, `explain_text`, `create_time`)
VALUES
	(1,'EXP-O5-qwen3-4b-1777191439127',5,'qwen3:4b',56,2400000.00,7.91,0.610,7.83,6132.80,100.00,64.00,74.00,85.00,'{\"candidateSource\":\"ai\",\"feasible\":false,\"riskLevel\":\"high\",\"violations\":[\"预测硫分0.61%超过订单上限0.60%\"],\"warnings\":[],\"scoreDetail\":\"质量评分：100（根据灰分、硫分、水分和发热量相对订单目标的偏差计算）；成本评分：64（根据候选煤种价格区间内的吨煤成本位置计算）；稳定性评分：74（根据库存覆盖倍数、执行后库存余量和组合煤种数量计算）；综合评分：85（综合评分=质量50%+成本20%+库存稳定性30%）\"}','预测硫分0.61%超过订单上限0.60%','【模型生成理由】AI方案名称：方案1：低硫高热值组合；策略：基于低硫订单优先低硫煤规则和发热量下限校验规则，优先使用硫分低且热值高的煤种补偿热值；物料理由：PB-REAL-YPH-20260427-CL：灰分8.9%低于订单上限14%，硫分0.68%接近但满足0.6%上限，发热量6988 kcal/kg远高于下限5500，作为主配煤种；PB-REAL-WCW-20260427-CL：灰分6.43%低于订单上限，硫分0.51%满足0.6%上限，发热量4850 kcal/kg略低于下限，但通过高热值煤补偿可满足热值需求；AI风险提示：硫分0.68%接近订单上限0.6%，需严格监控硫分波动\n【评分解释】组合为 营盘壕高热值精煤补充批次（PB-REAL-YPH-20260427-CL）60% + 准东五彩湾低硫动力煤补充批次（PB-REAL-WCW-20260427-CL）40%，预测灰分 7.91%、硫分 0.61%、发热量 6133 kcal/kg；质量分 100.00、成本分 64.00、稳定性分 74.00，存在约束边界压力。','2026-04-26 16:17:19'),
	(2,'EXP-O5-qwen3-4b-1777191439127',5,'qwen3:4b',57,2500000.00,8.16,0.630,7.27,6346.60,100.00,58.00,74.00,83.80,'{\"candidateSource\":\"ai\",\"feasible\":false,\"riskLevel\":\"high\",\"violations\":[\"预测硫分0.63%超过订单上限0.60%\"],\"warnings\":[],\"scoreDetail\":\"质量评分：100（根据灰分、硫分、水分和发热量相对订单目标的偏差计算）；成本评分：58（根据候选煤种价格区间内的吨煤成本位置计算）；稳定性评分：74（根据库存覆盖倍数、执行后库存余量和组合煤种数量计算）；综合评分：83.8（综合评分=质量50%+成本20%+库存稳定性30%）\"}','预测硫分0.63%超过订单上限0.60%','【模型生成理由】AI方案名称：方案3：高热值应急补偿；策略：基于发热量下限校验规则和低硫订单优先低硫煤规则，引入高热值煤种补偿热值；物料理由：PB-REAL-YPH-20260427-CL：灰分8.9%、硫分0.68%满足要求，发热量6988 kcal/kg作为主配煤种；PB-REAL-WCW-20260427-CL：灰分6.43%、硫分0.51%满足要求，发热量4850 kcal/kg提供热值补偿；AI风险提示：水分11.17%略高，需监控储运环节质量\n【评分解释】组合为 营盘壕高热值精煤补充批次（PB-REAL-YPH-20260427-CL）70% + 准东五彩湾低硫动力煤补充批次（PB-REAL-WCW-20260427-CL）30%，预测灰分 8.16%、硫分 0.63%、发热量 6347 kcal/kg；质量分 100.00、成本分 58.00、稳定性分 74.00，存在约束边界压力。','2026-04-26 16:17:19'),
	(3,'EXP-O16-qwen3-4b-1777192470815',16,'qwen3:4b',58,1257200.00,7.33,0.600,8.51,5841.40,100.00,73.30,79.00,88.36,'{\"candidateSource\":\"ai\",\"feasible\":true,\"riskLevel\":\"medium\",\"violations\":[],\"warnings\":[\"低硫高热值精煤产品（PB2026042501-CL）执行后余量低于1000吨\"],\"scoreDetail\":\"质量评分：100（根据灰分、硫分、水分和发热量相对订单目标的偏差计算）；成本评分：73.3（根据候选煤种价格区间内的吨煤成本位置计算）；稳定性评分：79（根据库存覆盖倍数、执行后库存余量和组合煤种数量计算）；综合评分：88.36（综合评分=质量50%+成本20%+库存稳定性30%）\"}','低硫高热值精煤产品（PB2026042501-CL）执行后余量低于1000吨','【模型生成理由】AI方案名称：方案3：准东五彩湾主导+高热值平衡；策略：高热值应急订单策略+低硫电煤成功案例；物料理由：PB-REAL-WCW-20260427-CL：准东五彩湾低硫煤（硫分0.51%）作为主配，满足低硫需求；PB-REAL-YPH-20260427-CL：营盘壕高热值精煤（发热量6988 kcal/kg）提供热值补偿；PB2026042501-CL：低硫高热值精煤（硫分0.68%）确保热值达标；AI风险提示：准东五彩湾煤水分较高（11.17%），需延长堆放周期\n【评分解释】组合为 准东五彩湾低硫动力煤补充批次（PB-REAL-WCW-20260427-CL）50% + 营盘壕高热值精煤补充批次（PB-REAL-YPH-20260427-CL）30% + 低硫高热值精煤产品（PB2026042501-CL）20%，预测灰分 7.33%、硫分 0.60%、发热量 5841 kcal/kg；质量分 100.00、成本分 73.30、稳定性分 79.00，满足当前主要约束。','2026-04-26 16:34:31'),
	(4,'EXP-O16-qwen3-4b-1777192470815',16,'qwen3:4b',59,1313200.00,7.57,0.610,7.95,6055.20,100.00,67.30,79.00,87.16,'{\"candidateSource\":\"ai\",\"feasible\":true,\"riskLevel\":\"medium\",\"violations\":[],\"warnings\":[\"低硫高热值精煤产品（PB2026042501-CL）执行后余量低于1000吨\"],\"scoreDetail\":\"质量评分：100（根据灰分、硫分、水分和发热量相对订单目标的偏差计算）；成本评分：67.3（根据候选煤种价格区间内的吨煤成本位置计算）；稳定性评分：79（根据库存覆盖倍数、执行后库存余量和组合煤种数量计算）；综合评分：87.16（综合评分=质量50%+成本20%+库存稳定性30%）\"}','低硫高热值精煤产品（PB2026042501-CL）执行后余量低于1000吨','【模型生成理由】AI方案名称：方案1：低硫高热值主配+准东五彩湾补偿；策略：低硫订单优先低硫煤规则+高热值应急订单策略；物料理由：PB-REAL-WCW-20260427-CL：准东五彩湾低硫煤（硫分0.51%）满足低硫订单要求，且高热值补偿潜力；PB-REAL-YPH-20260427-CL：营盘壕高热值精煤（发热量6988 kcal/kg）提供热值保障；PB2026042501-CL：低硫高热值精煤（硫分0.68%）作为热值补充，满足硫分要求；AI风险提示：准东五彩湾煤水分较高（11.17%），需确保堆放周期\n【评分解释】组合为 准东五彩湾低硫动力煤补充批次（PB-REAL-WCW-20260427-CL）40% + 营盘壕高热值精煤补充批次（PB-REAL-YPH-20260427-CL）40% + 低硫高热值精煤产品（PB2026042501-CL）20%，预测灰分 7.57%、硫分 0.61%、发热量 6055 kcal/kg；质量分 100.00、成本分 67.30、稳定性分 79.00，满足当前主要约束。','2026-04-26 16:34:31');

