	(10,'PB-REAL-PS-20260427-CL',2,4,NULL,NULL,'clean_coal','平朔洗选动力煤补充批次',5200.00,5200.00,'PROD-WH-PS-REAL',21.00,1.100,11.50,30.00,5200.00,'available','参考平朔动力煤公开指标构造：灰分约21%、硫分约1.1%、水分约11.5%、发热量约5200kcal/kg；适合宽硫成本型订单。','2026-04-25 17:26:16','2026-04-25 17:26:16'),
