# 转储表 rag_knowledge
# ------------------------------------------------------------

DROP TABLE IF EXISTS `rag_knowledge`;

CREATE TABLE `rag_knowledge` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `knowledge_code` varchar(64) NOT NULL COMMENT '知识编号',
  `title` varchar(200) NOT NULL COMMENT '知识标题',
  `knowledge_type` varchar(50) NOT NULL COMMENT '知识类型：rule/case/term/doc',
  `content` text NOT NULL COMMENT '知识正文',
  `source_table` varchar(100) DEFAULT NULL COMMENT '来源表',
  `source_id` bigint DEFAULT NULL COMMENT '来源记录ID',
  `tags` varchar(500) DEFAULT NULL COMMENT '标签',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1启用，0停用',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_knowledge_code` (`knowledge_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='RAG统一知识检索表';

LOCK TABLES `rag_knowledge` WRITE;
/*!40000 ALTER TABLE `rag_knowledge` DISABLE KEYS */;

INSERT INTO `rag_knowledge` (`id`, `knowledge_code`, `title`, `knowledge_type`, `content`, `source_table`, `source_id`, `tags`, `status`, `create_time`, `update_time`)
VALUES
	(1,'K-RULE-001','低硫订单优先低硫煤规则','rule','当订单硫分上限较低时，应优先选择硫分较低且煤质稳定的产品批次参与配煤；若硫分预测值接近订单上限，应给出风险提示并建议增加低硫煤比例。','rule_knowledge',1,'低硫,配煤规则,硫分,风险控制',1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(2,'K-RULE-002','库存可用性与锁定规则','rule','参与配煤的产品批次必须存在可用库存，方案使用量不得超过可用库存。方案被选择或执行后，应在库存中体现锁定量或扣减量。','rule_knowledge',5,'库存,锁定量,可执行性,产品批次',1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(3,'K-CASE-001','低硫高热值商品煤成功案例','case','订单O2026042501要求5000吨低硫高热值动力煤，方案P2026042501-A采用PB2026042501-CL 60%与PB2026042502-CL 40%，最终产品FP2026042501质检合格并发运。','case_sample',1,'成功案例,低硫,高热值,发运',1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(4,'K-CASE-002','严格低硫订单风险反馈案例','case','订单O2026042502硫分上限0.60%，方案P2026042502-RISK理论预测接近上限，最终产品FP2026042502实测硫分0.610%，说明严格低硫订单需要保留更大质量余量。','case_sample',2,'风险案例,硫分超标,反馈,质量余量',1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(5,'K-TERM-001','批次血缘追溯说明','term','批次血缘用于记录父批次到子批次的业务关系，例如原煤批次进入洗选批次、洗选批次产出产品批次、产品批次混配生成最终产品、最终产品发运形成发运批次。',NULL,NULL,'批次血缘,追溯,数据链条',1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(6,'K-DOC-001','煤矿智能配煤全链路流程说明','doc','系统业务链路包括矿区煤种煤质、原煤生产、原煤入仓、洗选加工、洗后产品、产品库存、订单驱动配煤、最终产品质检、发运交付和执行反馈。',NULL,NULL,'全链路,原煤生产,洗选加工,最终产品',1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(7,'K-DOC-002','多阶段煤质数据说明','doc','煤质数据应按采样阶段区分，包括geological地质煤质、raw_coal原煤煤质、wash_feed入洗煤质、clean_coal洗后产品煤质、mixed_product混配产品煤质和final_product最终商品煤煤质。',NULL,NULL,'煤质,采样阶段,质量档案',1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(8,'K-DOC-003','商品煤分质管理说明','doc','商品煤生产、加工、储运、销售等环节均应重视质量管理。不同质量商品煤应分质堆存、分质装车，并建立商品煤质量档案。',NULL,NULL,'商品煤质量,分质堆存,分质装车,质量档案',1,'2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(9,'RAG-RK-TUNE-001','低硫订单优先低硫煤规则','rule','规则类型：质量约束。规则内容：当订单硫分上限小于等于0.60%时，应优先选择硫分低于0.45%的煤种；硫分高于0.80%的煤种原则上不参与或低比例参与。。适用范围：低硫电煤、环保限硫订单','rule_knowledge',9,'质量约束,sulfur_content,coal_type',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(10,'RAG-RK-TUNE-002','高灰煤限配规则','rule','规则类型：配比约束。规则内容：当煤种灰分高于20%时，若订单灰分上限小于18%，该煤种配比建议不超过20%；若订单灰分上限小于14%，原则上不推荐使用。。适用范围：高灰动力煤参与配煤','rule_knowledge',10,'配比约束,ash_content,coal_type',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(11,'RAG-RK-TUNE-003','高水分煤限配规则','rule','规则类型：配比约束。规则内容：当煤种水分高于15%时，若订单水分上限小于12%，该煤种配比建议不超过15%；若订单水分上限小于10%，原则上不推荐使用。。适用范围：褐煤、高水分煤','rule_knowledge',11,'配比约束,moisture_content,coal_type',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(12,'RAG-RK-TUNE-004','高热值补偿规则','rule','规则类型：经验规则。规则内容：当订单发热量下限高于5800 kcal/kg时，应引入高热值煤进行补偿，但应同时控制成本和库存余量。。适用范围：高热值订单','rule_knowledge',12,'经验规则,calorific_value,coal_type',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(13,'RAG-RK-TUNE-005','成本优先订单规则','rule','规则类型：经验规则。规则内容：当订单优先级为1且质量约束较宽松时，可优先使用低成本煤种，但必须保证灰分、硫分、水分和热值全部满足硬约束。。适用范围：成本优先订单','rule_knowledge',13,'经验规则,cost,quality,coal_type',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(14,'RAG-RK-TUNE-006','库存安全余量规则','rule','规则类型：库存约束。规则内容：生成方案后，任一参与煤种执行后可用库存低于800吨时，应提示库存风险；低于300吨时不建议作为推荐方案。。适用范围：库存稳定性评估','rule_knowledge',14,'库存约束,available_quantity,coal_type',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(15,'RAG-RK-TUNE-007','中硫煤限配规则','rule','规则类型：配比约束。规则内容：当煤种硫分在0.80%至1.00%之间时，若订单硫分上限小于0.90%，该煤种配比建议不超过25%。。适用范围：中硫动力煤','rule_knowledge',15,'配比约束,sulfur_content,coal_type',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(16,'RAG-RK-TUNE-008','气化用煤挥发分参考规则','rule','规则类型：质量约束。规则内容：气化用煤应关注挥发分与热值，挥发分过低的无烟煤、贫瘦煤不宜大比例参与气化用煤方案。。适用范围：煤化工气化用煤','rule_knowledge',16,'质量约束,volatile_content,calorific_value,coal_type',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(24,'RAG-CS-TUNE-001','低硫电煤成功案例','case','订单描述：5000吨低硫电煤，要求硫分≤0.60%、热值≥5500 kcal/kg。 配煤方案：神府低硫长焰煤50% + 鄂尔多斯低硫煤30% + 准东五彩湾高水分煤20%。 执行结果：最终硫分0.47%，灰分9.8%，水分8.9%，热值5740 kcal/kg，满足订单约束。 质量结果：合格：低硫余量充足，热值达标','case_sample',4,'历史案例,配煤方案,质量反馈',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(25,'RAG-CS-TUNE-002','成本优先电煤成功案例','case','订单描述：8000吨经济煤，灰分≤22%、硫分≤1.20%、热值≥4800。 配煤方案：平朔高灰动力煤45% + 准东五彩湾高水分煤35% + 晋北中硫动力煤20%。 执行结果：最终灰分18.6%，硫分0.71%，热值5050 kcal/kg，成本较低。 质量结果：合格：成本优势明显','case_sample',5,'历史案例,配煤方案,质量反馈',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(26,'RAG-CS-TUNE-003','高水分煤超配风险案例','case','订单描述：3000吨环保电煤，水分≤9%、硫分≤0.60%。 配煤方案：准东五彩湾高水分煤50% + 神府低硫长焰煤50%。 执行结果：最终水分9.7%，超过订单上限，虽硫分达标但水分不合格。 质量结果：不合格：水分超限','case_sample',6,'历史案例,配煤方案,质量反馈',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(27,'RAG-CS-TUNE-004','高热值应急订单成功案例','case','订单描述：2500吨高热值订单，要求热值≥6200 kcal/kg。 配煤方案：榆林高热值不粘煤60% + 神府低硫长焰煤40%。 执行结果：最终热值6460 kcal/kg，硫分0.40%，成本偏高但满足应急要求。 质量结果：合格：热值余量充足','case_sample',7,'历史案例,配煤方案,质量反馈',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(28,'RAG-CS-TUNE-005','中硫煤限配案例','case','订单描述：5200吨中等质量订单，硫分≤0.85%、热值≥5300。 配煤方案：晋北中硫动力煤20% + 鄂尔多斯低硫煤40% + 神府低硫长焰煤40%。 执行结果：最终硫分0.56%，热值5740 kcal/kg，质量稳定。 质量结果：合格：中硫煤比例受控','case_sample',8,'历史案例,配煤方案,质量反馈',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(29,'RAG-CS-TUNE-006','褐煤低成本边界案例','case','订单描述：10000吨低价保供订单，热值≥4300、水分≤18%。 配煤方案：蒙西低成本褐煤40% + 平朔高灰动力煤30% + 准东五彩湾高水分煤30%。 执行结果：最终水分16.4%，热值4550 kcal/kg，满足低价保供要求。 质量结果：合格：低成本但质量余量较小','case_sample',9,'历史案例,配煤方案,质量反馈',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(30,'RAG-CS-TUNE-007','严格商品煤失败案例','case','订单描述：3200吨严格商品煤，灰分≤10%、硫分≤0.55%、水分≤8%。 配煤方案：神府低硫长焰煤45% + 鄂尔多斯低硫煤35% + 准东五彩湾煤20%。 执行结果：最终水分8.7%，超过上限；原因是高水分煤比例偏高。 质量结果：不合格：水分边界控制不足','case_sample',10,'历史案例,配煤方案,质量反馈',1,'2026-04-25 22:05:30','2026-04-25 22:05:30'),
	(31,'RAG-CS-TUNE-008','气化用煤成功案例','case','订单描述：3600吨煤化工气化用煤，挥发分参考34%、热值≥5600、硫分≤0.80%。 配煤方案：宁东气化用煤50% + 神府低硫长焰煤30% + 榆林高热值不粘煤20%。 执行结果：最终挥发分33.9%，热值6020 kcal/kg，硫分0.48%，满足气化用煤要求。 质量结果：合格：气化指标匹配较好','case_sample',11,'历史案例,配煤方案,质量反馈',1,'2026-04-25 22:05:30','2026-04-25 22:05:30');

/*!40000 ALTER TABLE `rag_knowledge` ENABLE KEYS */;
UNLOCK TABLES;


# 转储表 rag_retrieval_log
# ------------------------------------------------------------

DROP TABLE IF EXISTS `rag_retrieval_log`;

CREATE TABLE `rag_retrieval_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `biz_type` varchar(50) NOT NULL COMMENT '业务类型：blend_generate/chat/search',
  `biz_id` bigint DEFAULT NULL COMMENT '业务ID，如方案ID',
  `query_text` varchar(1000) NOT NULL COMMENT '检索查询文本',
  `keywords` varchar(1000) DEFAULT NULL COMMENT '抽取出的关键词',
  `retrieved_ids` varchar(1000) DEFAULT NULL COMMENT '命中的知识ID列表',
  `model_name` varchar(100) DEFAULT NULL COMMENT '调用模型名称',
  `prompt_text` mediumtext COMMENT '最终提示词',
  `model_output` mediumtext COMMENT '模型输出',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_rag_log_biz` (`biz_type`,`biz_id`),
  KEY `idx_rag_log_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='RAG检索与生成日志表';

